import zipfile, re
z=zipfile.ZipFile('/root/inventory_report_ready.hwpx')
xml=z.read('Contents/section0.xml').decode('utf-8', errors='replace')
# check modified paragraphs (by known ids) don't have linesegarray
modified_ids={'1','2','3','5','6','7','8','11','12','13','15','16'}
for pid in sorted(modified_ids, key=int):
    m=re.search(rf'(<hp:p\b[^>]*\bid="{pid}"[^>]*>)(.*?)(</hp:p>)', xml, flags=re.DOTALL)
    if not m:
        print('missing paragraph id', pid)
        continue
    inner=m.group(2)
    if '<hp:linesegarray' in inner or '<hp:lineSegArray' in inner:
        print('FAIL linesegarray still in modified paragraph', pid)
        break
else:
    print('Modified paragraphs linesegarray: OK')
# check some unmodified paragraph ids still have linesegarray where originally present (heuristic)
for pid in ['0','10','17']:
    m=re.search(rf'(<hp:p\b[^>]*\bid="{pid}"[^>]*>)(.*?)(</hp:p>)', xml, flags=re.DOTALL)
    if m:
        print('para',pid,'has linesegarray?', '<hp:linesegarray' in m.group(2))
PY

